import '@servicenow/sdk/global'
import { StringColumn, IntegerColumn, BooleanColumn } from '@servicenow/sdk/core'
import { Flow, trigger, wfa } from '@servicenow/sdk/automation'

/**
 * Test flow for SetFlowVariables with basic literal values
 */
export const setFlowVariablesBasic = Flow(
    {
        $id: Now.ID['set-flow-variables-basic'],
        name: 'SetFlowVariables Basic Test',
        description: 'Test SetFlowVariables with string, number, and boolean values',
        flowPriority: 'MEDIUM',
        runAs: 'system',
        runWithRoles: [],
        flowVariables: {
            status: StringColumn({
                label: 'Status',
                mandatory: false,
            }),
            count: IntegerColumn({
                label: 'Count',
                mandatory: false,
            }),
            isActive: BooleanColumn({
                label: 'Is Active',
                mandatory: false,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['set-flow-vars-basic-trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-basic-instance'],
                annotation: 'Set basic flow variables',
            },
            params.flowVariables,
            {
                status: 'active',
                count: 42,
                isActive: true,
            }
        )
    }
)
